	/** 
	 * jumpstart the process by instantiating2 Cart
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		cartId = CartService.getCartInstance()
		.createCart( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		CartService.getCartInstance()
				.createCart( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.cartSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Cart : " + successValue.getCartId());
							  if (successValue.getCartId().equals(cartId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfCartList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Cart test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on cart consumed")
					);
			subscriber.cartSubscribe( cartId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Cart : " + successValue.getCartId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfCartList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on cart for cartId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Cart. 
	 */
	protected Cart read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Cart" );

		Cart entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Cart with primary key" );
		msg.append( cartId );
		
		CartFetchOneSummary fetchOneSummary = new CartFetchOneSummary( cartId );

		try {
			entity = CartService.getCartInstance().getCart( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Cart " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Cart.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Cart." );

		StringBuilder msg = new StringBuilder( "Failed to update a Cart : " );        
		Cart entity = read();
		UpdateCartCommand command = generateUpdateCommand();
		command.setCartId(entity.getCartId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Cart." );

			// for use later on...
			cartId = entity.getCartId();

			CartService proxy = CartService.getCartInstance();  

			proxy.updateCart( command ).get();

			LOGGER.info( "-- Successfully saved Cart - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + cartId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Cart.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Cart." );

		Cart entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Cart with id " + cartId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Cart with id " + cartId );

			throw e;
		}

		try{
			CartService.getCartInstance().delete( new DeleteCartCommand( entity.getCartId() ) ).get();
			LOGGER.info( "-- Successfully deleted Cart with id " + cartId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Cart with id " + cartId );

			throw e;
		}
	}

	/**
	 * get all Carts.
	 */
	protected List<Cart> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Carts:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Cart : " );        
		List<Cart> collection  = new ArrayList<>();

		try {
			// call the static get method on the CartService
			collection = CartService.getCartInstance().getAllCart();
			assertNotNull( collection, "An Empty collection of Cart was incorrectly returned.");
			
			// Now print out the values
			Cart entity = null;            
			Iterator<Cart> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getCartId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

